insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values
('shipping.overview','ارسال حرفه‌ای','Shipping Pro یک سرویس قراردادی جداست و روش‌های ارسال، هزینه و زمان تقریبی تحویل را مدیریت می‌کند.','فعال بودن Commerce به معنی فعال بودن Shipping Pro نیست.','Shipping Pro','Shipping Pro is a separate contractual add-on for delivery methods, pricing and estimated delivery times.','Commerce access does not automatically enable Shipping Pro.',true),
('shipping.settings','تنظیمات ارسال','مبدا، ارز و آستانه ارسال رایگان را تنظیم کن. خود ماژول نیز می‌تواند بدون حذف تنظیمات خاموش شود.','خاموش کردن ماژول نباید اطلاعات روش‌های ارسال را حذف کند.','Shipping settings','Configure origin, currency and the free-shipping threshold. The module can be disabled without deleting its configuration.','Disabling Shipping Pro must not delete shipping configuration.',true),
('shipping.methods','روش‌های ارسال','برای هر روش نام، مدل قیمت، ارز، زمان تقریبی تحویل و شرط ارسال رایگان تعریف می‌شود.',null,'Shipping methods','Each method can define its name, pricing model, currency, delivery estimate and free-shipping condition.',null,true),
('shipping.zones','محدوده‌های ارسال','در نسخه‌های بعدی هر روش می‌تواند به کشور، منطقه یا محدوده کدپستی مشخص محدود شود.',null,'Shipping zones','Methods can be scoped to countries, regions or postal-code areas as the delivery engine expands.',null,true),
('shipping.quote','امنیت هزینه ارسال','هزینه ارسال باید از تنظیمات معتبر سایت در سرور محاسبه شود؛ عددی که مرورگر ارسال می‌کند قابل اعتماد نیست.','هرگز shipping_total ارسالی از مرورگر را مبلغ نهایی تلقی نکن.','Shipping quote security','Shipping must be calculated server-side from the tenant configuration; browser-supplied totals are untrusted.','Never trust a browser-supplied shipping_total as the final amount.',true)
